<?php if (!isset($route)) { http_response_code(404); exit; } ?>
<?php if ($analysisItems === []): ?><div class="empty-state"><h3>No hay señales para esta consulta.</h3><p>Esto no certifica el cumplimiento ni la autenticidad documental.</p></div><?php else: ?>
<ul class="dashboard-items analysis-items">
<?php foreach ($analysisItems as $item): $url=analysis_destination($item['destino'] ?? null); $peer=analysis_destination($item['relacionado'] ?? null); ?>
<li><div><p><span class="badge <?= ($item['severidad'] ?? '') === 'WARNING' ? 'badge-warning' : 'badge-neutral' ?>"><?= e($item['severidad']) ?></span> · <?= e($item['clasificacion']) ?></p><h3><?= e($item['titulo']) ?></h3><p class="dashboard-resource-name"><?= e($item['nombre']) ?> · <?= e($item['recurso']) ?> #<?= e($item['recurso_id']) ?></p><p><?= e($item['explicacion']) ?></p><details><summary>¿Por qué se marcó?</summary><p>Regla: <?= e($item['regla']) ?></p><ul><?php foreach ($item['evidencia_tecnica'] as $technical): ?><li><?= e($technical) ?></li><?php endforeach; ?></ul><p>Evaluado: <?= e(display_date($item['evaluado_en'])) ?></p></details>
<?php if ($peer!==null): ?><p><a class="text-link" href="<?= e($peer) ?>">Consultar recurso relacionado<?php if (isset($item['relacionado']['version_id'])): ?> · versión #<?= e($item['relacionado']['version_id']) ?><?php endif; ?></a></p><?php endif; ?>
</div><div class="analysis-actions"><?php if ($url!==null): ?><a class="text-link" href="<?= e($url) ?>">Consultar recurso</a><?php endif; ?><?php if (($item['destino']['pagina'] ?? '')==='documento' && analysis_id($item['destino']['id'] ?? null)!==null): ?><a class="text-link" href="<?= e(page_url('analisis', ['documento_id'=>$item['destino']['id']])) ?>">Analizar documento</a><?php endif; ?></div></li>
<?php endforeach; ?></ul><?php endif; ?>
